/// <summary>
/// Displays selling Price 
/// </summary>
/// <returns>Price + Meterial price + Energy price</returns>
[SysClientCacheDataMethodAttribute(true)]
display KCS_PRMPriceSales KCS_PRMPriceSales()
{
    return this.Amount + this.KCS_PRMMarkupMaterial + this.KCS_PRMMarkupEnergy;
}
